begin;
select no_plan();
set local role anon;
select throws_ok($$select public.begin_ai_request('20000000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001')$$, '42501', null, 'anonymous cannot reserve AI requests');
set local role authenticated;
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000001', true);
select throws_ok($$select public.begin_ai_request('20000000-0000-0000-0000-000000000002','80000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001')$$, '42501', 'Shop access denied', 'owner cannot process another shop input');
select is(public.begin_ai_request('20000000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001'), 'ready', 'verified owner can reserve a request');
select is(public.begin_ai_request('20000000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001'), 'processing', 'duplicate request cannot trigger another provider call');
select lives_ok($$select public.complete_ai_draft('81000000-0000-0000-0000-000000000001', '{"title":"AI rice","price_minor":null,"quantity":null,"unit":null,"source_type":"text"}', '{"warnings":["Check price"]}', 'Original private input', null)$$, 'AI result saves privately as draft');
select is((select status from public.offers where id='80000000-0000-0000-0000-000000000001'), 'draft', 'AI cannot auto-publish');
select is((select transcript from public.offer_sources where offer_id='80000000-0000-0000-0000-000000000001'), 'Original private input', 'source retained privately');
select is(public.begin_ai_request('20000000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000001','81000000-0000-0000-0000-000000000001'), 'completed', 'completed retry returns existing draft');
select lives_ok($$select public.save_offer_draft('20000000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000001',1,'{"title":"Owner corrected","price_minor":9900}','82000000-0000-0000-0000-000000000001')$$, 'owner can correct extracted fields');
select is((select corrections->>'title' from public.offer_sources where offer_id='80000000-0000-0000-0000-000000000001'), 'Owner corrected', 'owner corrections are retained');
select is(public.begin_ai_request('20000000-0000-0000-0000-000000000001','80000000-0000-0000-0000-000000000002','81000000-0000-0000-0000-000000000002'), 'ready', 'photo request reserved');
select throws_ok($$select public.complete_ai_draft('81000000-0000-0000-0000-000000000002','{"title":"Photo draft","source_type":"photo"}','{}','','20000000-0000-0000-0000-000000000001/81000000-0000-0000-0000-000000000002.jpg/arbitrary')$$, '22023', 'Invalid AI source', 'nested or arbitrary source filenames are rejected');
select throws_ok($$select public.complete_ai_draft('81000000-0000-0000-0000-000000000002','{"title":"Photo draft","source_type":"photo"}','{}','','20000000-0000-0000-0000-000000000001/81000000-0000-0000-0000-000000000002.webm')$$, '22023', 'Invalid AI source', 'media extension must match source mode');
select throws_ok($$select public.complete_ai_draft('81000000-0000-0000-0000-000000000002','{"title":"Photo draft","source_type":"photo"}','{}','','20000000-0000-0000-0000-000000000001/81000000-0000-0000-0000-000000000002.jpg')$$, '22023', 'Invalid AI source', 'source must exist in private storage');
select set_config('request.jwt.claim.sub', '10000000-0000-0000-0000-000000000002', true);
select is((select count(*)::int from public.offer_sources where offer_id='80000000-0000-0000-0000-000000000001'), 0, 'other owner cannot read extraction sources');
select throws_ok($$select public.complete_ai_draft('81000000-0000-0000-0000-000000000001','{}','{}',null,null)$$, '42501', 'Request access denied', 'other owner cannot replace extraction source');
set local role anon;
select is((select count(*)::int from public.public_offers where id='80000000-0000-0000-0000-000000000001'), 0, 'AI draft never enters public projection');
select * from finish();
rollback;
